//! Actual v22 Java ModernQuestLifeProtocolTest output, never a Rust encoder oracle.
use super::*;
use crate::modern_lito::{application_protocol as app, npc_protocol as npc};
const BEFORE: &str = "";
const DEAD: &str = "";
const REVIVED: &str = "";
fn bytes(s: &str) -> Vec<u8> {
    s.as_bytes()
        .chunks_exact(2)
        .map(|v| u8::from_str_radix(std::str::from_utf8(v).unwrap(), 16).unwrap())
        .collect()
}
pub(crate) fn sample(which: &str) -> npc::Reply {
    let value = match which {
        "before" => BEFORE,
        "dead" => DEAD,
        "revived" => REVIVED,
        _ => panic!("unknown Java life fixture"),
    };
    match app::decode_response_version(&bytes(value), 22)
        .unwrap()
        .response
    {
        app::Response::Npc(r) => r,
        _ => panic!("wrong kind"),
    }
}
#[test]
fn actual_java_death_and_spawn_confirmation_preserve_one_authority_and_old_receipt_life() {
    let before = sample("before");
    let dead = sample("dead");
    let revived = sample("revived");
    assert!(npc::follows(Some(&before), &dead));
    assert!(npc::follows(Some(&dead), &revived));
    assert!(npc::follows(Some(&before), &revived));
    let a = &dead.frame.as_ref().unwrap().combat;
    let b = &revived.frame.as_ref().unwrap().combat;
    let proof = confirmation(a, 1).unwrap();
    assert_eq!(proof.incarnation, 1);
    assert_eq!(proof.death_revision as u64, revived.echo.sequence);
    assert_eq!(revived.echo.action, npc::Action::ConfirmDeath);
    assert!(revived.echo.target().is_none());
    assert!(revived.echo.objective().is_none());
    assert_eq!(a.vital(1).unwrap().hp, 0);
    assert_eq!(b.vital(1).unwrap().hp, 1);
    assert_eq!(
        b.world.actor(1).unwrap().position,
        life(&b.world, 1).unwrap().spawn
    );
    assert_ne!(
        a.world.actor(1).unwrap().position,
        b.world.actor(1).unwrap().position
    );
    assert_eq!(life(&b.world, 1).unwrap().incarnation(), 2);
    assert_eq!(respawn_gain(b, 1), 1);
    assert!(respawned(a, b, 1));
    assert_eq!(
        revived.frame.as_ref().unwrap().exchanges[0].participant_life,
        1
    );
    assert!(confirmation(b, 1).is_none());
    assert!(!npc::follows(Some(&revived), &dead));
    assert_eq!(a.world.room.members.len(), 2);
    assert_eq!(a.world.quest.as_ref().unwrap().lives.len(), 1);
}
#[test]
fn forged_resurrection_hp_counters_spawn_and_life_receipts_are_rejected() {
    let dead = sample("dead");
    let revived = sample("revived");
    for change in 0..7 {
        let mut altered = revived.clone();
        let f = altered.frame.as_mut().unwrap();
        match change {
            0 => f.combat.world.quest.as_mut().unwrap().lives[0].hp_gain += 1,
            1 => f.combat.world.quest.as_mut().unwrap().lives[0].respawns += 1,
            2 => f.combat.world.quest.as_mut().unwrap().lives[0].death_revision = 0,
            3 => f.combat.world.quest.as_mut().unwrap().lives[0].spawn.x += 1,
            4 => f.exchanges[0].participant_life = 2,
            5 => altered.echo.life += 1,
            _ => f.combat.vitals[0].hp = 0,
        }
        assert!(altered.validate().is_err(), "case {change}");
        assert!(!npc::follows(Some(&dead), &altered));
    }
    let mut hidden = dead.clone();
    hidden
        .frame
        .as_mut()
        .unwrap()
        .combat
        .world
        .quest
        .as_mut()
        .unwrap()
        .lives[0]
        .lane = 1;
    assert!(hidden.validate().is_err());
    let mut old_spawn = dead.clone();
    old_spawn
        .frame
        .as_mut()
        .unwrap()
        .combat
        .world
        .quest
        .as_mut()
        .unwrap()
        .lives[0]
        .spawn
        .x += 1;
    assert!(old_spawn.validate().is_ok());
    assert!(
        !npc::follows(Some(&sample("before")), &old_spawn),
        "immutable birth policy"
    );
}
#[test]
fn complete_java_bytes_reject_all_truncations_downgrades_and_unnegotiated_life_capability() {
    for s in [BEFORE, DEAD, REVIVED] {
        let encoded = bytes(s);
        for n in 0..encoded.len() {
            assert!(
                app::decode_response_version(&encoded[..n], 22).is_err(),
                "cut {n}"
            );
        }
        assert!(app::decode_response_version(&encoded, 21).is_err());
    }
    let mut r = sample("before");
    let w = &mut r.frame.as_mut().unwrap().combat.world;
    w.descriptor.as_mut().unwrap().features &= !world::MatchDescriptor::QUEST_LIVES;
    assert!(r.validate().is_err());
    let old = crate::modern_lito::quest_protocol::tests::sample("before");
    assert!(old
        .frame
        .as_ref()
        .unwrap()
        .combat
        .world
        .quest
        .as_ref()
        .unwrap()
        .lives
        .is_empty());
}
